package com.farm2market.config;
import com.farm2market.entity.*; import com.farm2market.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class SeedConfig { @Bean CommandLineRunner seed(UserRepository users,ProductRepository products,PasswordEncoder enc){return a->{if(users.count()>0)return; User admin=new User();admin.setName("Marketplace Admin");admin.setEmail("admin@farm2market.com");admin.setPassword(enc.encode("Admin@123"));admin.setRole(Role.ADMIN);users.save(admin); User farmer=new User();farmer.setName("Raj Farms");farmer.setEmail("farmer@farm2market.com");farmer.setPassword(enc.encode("Farmer@123"));farmer.setRole(Role.FARMER);farmer.setLocation("Saswad, Purandar, Pune");users.save(farmer); User buyer=new User();buyer.setName("Aarav Buyer");buyer.setEmail("buyer@farm2market.com");buyer.setPassword(enc.encode("Buyer@123"));buyer.setRole(Role.BUYER);users.save(buyer); String[][] data={{"Tomato","VEGETABLE","30","500","Saswad, Purandar, Pune"},{"Onion","VEGETABLE","28","800","Narayangaon, Pune"},{"Potato","VEGETABLE","25","1000","Baramati, Pune"},{"Cauliflower","VEGETABLE","45","300","Saswad, Pune"},{"Fig / Anjeer","FRUIT","180","200","Purandar, Pune"},{"Guava","FRUIT","65","350","Wai, Satara"},{"Banana","FRUIT","48","600","Junnar, Pune"},{"Mango","FRUIT","120","250","Ratnagiri"},{"Marigold","FLOWER","90","150","Pune"}}; for(String[] d:data){Product p=new Product();p.setFarmer(farmer);p.setName(d[0]);p.setCategory(Category.valueOf(d[1]));p.setPricePerKg(Double.valueOf(d[2]));p.setAvailableQuantity(Double.valueOf(d[3]));p.setMinimumOrderQuantity(1d);p.setUnit("kg");p.setQualityGrade("A");p.setLocation(d[4]);products.save(p);}};}}
